def run_bst(root, k):
    stack, node = [], root
    while stack or node is not None:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        k -= 1
        if k == 0:
            return node.val
        node = node.right
    return -1

def run_bst(root, target):
    best = None
    while root is not None:
        if best is None or (abs(root.val - target), root.val) < (abs(best - target), best):
            best = root.val
        root = root.left if target < root.val else root.right
    return best

def run_bst(root, low, high):
    best = None
    while root is not None:
        if root.val > high:
            root = root.left
        elif root.val < low:
            root = root.right
        else:
            best = root.val
            root = root.right
    return best

def run_bst(root):
    keys = []
    def visit(node):
        if node is not None:
            visit(node.left)
            keys.append(node.val)
            visit(node.right)
    visit(root)
    return keys[-2] if len(keys) >= 2 else None

def run_bst(root):
    if root is None:
        return 0
    return 1 + run_bst(root.left) + run_bst(root.right)

def run_bst(root):
    if root is None:
        return 0
    if root.left is None and root.right is None:
        return 1
    return run_bst(root.left) + run_bst(root.right)

def run_bst(root):
    if root is None:
        return -1
    return 1 + max(run_bst(root.left), run_bst(root.right))

def run_bst(root, a, b):
    while root is not None:
        if a < root.val and b < root.val:
            root = root.left
        elif a > root.val and b > root.val:
            root = root.right
        else:
            return root.val
    return None
